const items = $input.all();
const result = [];

for (const item of items) {
  const data = item.json;

  let lignes = data.lignes;

  // Normalisation : gérer les différents formats possibles
  if (!lignes) {
    lignes = [];
  } else if (Array.isArray(lignes)) {
    // déjà un tableau, rien à faire
  } else if (lignes.item !== undefined) {
    // objet du type { item: {...} } ou { item: [...] }
    lignes = Array.isArray(lignes.item) ? lignes.item : [lignes.item];
  } else if (typeof lignes === 'object') {
    // objet unique sans wrapper "item" -> le traiter comme une seule ligne
    lignes = [lignes];
  } else {
    lignes = [];
  }

  // Normalisation de flag_hors_gamme en booléen réel
  let flagHorsGamme = data.flag_hors_gamme;
  if (typeof flagHorsGamme === 'boolean') {
    // déjà un booléen, rien à faire
  } else if (typeof flagHorsGamme === 'string') {
    flagHorsGamme = flagHorsGamme.trim().toLowerCase() === 'true';
  } else if (typeof flagHorsGamme === 'number') {
    flagHorsGamme = flagHorsGamme === 1;
  } else {
    flagHorsGamme = false;
  }

  for (const ligne of lignes) {
    // Force quantite_disponible en integer, en gérant null/undefined/vide/"null"
    let qte = ligne.quantite_disponible;
    if (qte === null || qte === undefined || qte === '' || qte === 'null') {
      qte = null;
    } else {
      qte = parseInt(qte, 10);
      if (isNaN(qte)) qte = null;
    }

    // Normalisation de marque_proposee : 0, "0", "", "null", undefined -> null
    let marqueProposee = ligne.marque_proposee;
    if (
      marqueProposee === null ||
      marqueProposee === undefined ||
      marqueProposee === '' ||
      marqueProposee === 'null' ||
      marqueProposee === 0 ||
      marqueProposee === '0'
    ) {
      marqueProposee = null;
    }

    result.push({
      json: {
        rfq_number: data.rfq_number,
        uuid: data.uuid,
        fournisseur: data.fournisseur,
        date_reception: data.date_reception,
        conditions_paiement: data.conditions_paiement,
        devise: data.devise,
        flag_hors_gamme: flagHorsGamme,
        validite_offre: data.validite_offre,
        remarques_generales: data.remarques_generales,
        ...ligne,
        marque_proposee: marqueProposee,
        quantite_disponible: qte
      }
    });
  }
}

return result;

