const items = $input.all();
const result = [];

for (const item of items) {
  const stdout = item.json.stdout || '';
  const stderr = item.json.stderr || '';

  let output_path = null;
  let success = false;
  let error = null;
  let rfq_date_code = null;
  let rfq_number = null;

  try {
    const parsed = JSON.parse(stdout.trim());
    output_path = parsed.output ?? null;
    success = parsed.success === true;
    error = parsed.error ?? null;

    if (output_path) {
      const nomFichier = output_path.split(/[\\/]/).pop();
      rfq_date_code = nomFichier.replace(/\.pdf$/i, '');

      // Extrait juste le code RFQ (ex: RFQ-2026-0718020300-50E5)
      const match = rfq_date_code.match(/^(RFQ-\d{4}-\d+-[A-Z0-9]{4})/i);
      rfq_number = match ? match[1].toUpperCase() : null;
    }
  } catch (e) {
    error = `Parsing échoué. stdout: "${stdout}" | stderr: "${stderr}"`;
  }

  result.push({
    json: {
      success: success,
      pdf_path: output_path,
      rfq_date_code: rfq_date_code,
      rfq_number: rfq_number,
      error: error
    }
  });
}

return result;

// Récupérer le sujet de l'email
const subject = $("Edit Fields6").first().json.subject || '';

// Patterns possibles dans le sujet
const patternRFQ = /RFQ-\d{4}-\d+-[A-Z0-9]{4}/i;                    // RFQ-2026-123-AB12
const patternRFPN = /RFPN-\d{4}-\d+-[A-Z0-9]{4}/i;                  // RFPN-2026-123-AB12
const patternRFM = /RFM-\d{4}-\d+-[A-Z0-9]{4}/i;                    // RFM-2026-123-AB12
const patternRFQ_Auto = /RFQ-\d{8}-\d{4}(?!-\d)/i;                  // RFQ-20260731-0002 

let rfq_number = null;
let rfpn_number = null;
let rfm_number = null;
let rfq_auto_number = null;

const matchRFQ_Auto = subject.match(patternRFQ_Auto);
if (matchRFQ_Auto) {
  rfq_auto_number = matchRFQ_Auto[0].replace('#', '').toUpperCase().trim();
}

const matchRFQ = subject.match(patternRFQ);
if (matchRFQ) {
  rfq_number = matchRFQ[0].replace('#', '').toUpperCase().trim();
}

const matchRFPN = subject.match(patternRFPN);
if (matchRFPN) {
  rfpn_number = matchRFPN[0].replace('#', '').toUpperCase().trim();
}

const matchRFM = subject.match(patternRFM);
if (matchRFM) {
  rfm_number = matchRFM[0].replace('#', '').toUpperCase().trim();
}

// Unifier le numero RFQ trouve, quel que soit le format
const rfq_final = rfq_auto_number || rfq_number || null;

// Verifier si au moins un identifiant a ete trouve
if (!rfq_final && !rfpn_number && !rfm_number) {
  return {
    success: false,
    error: 'Aucun numéro RFQ, RFPN ou RFM trouvé dans le sujet',
    subject_recu: subject,
    rfq_number: null,
    rfpn_number: null,
    rfm_number: null
  };
}

// Determiner le type de reference dominant
let type_reference;
if (rfpn_number) {
  type_reference = 'RFPN';
} else if (rfm_number) {
  type_reference = 'RFM';
} else {
  type_reference = 'RFQ';
}

// Retourner les donnees
return {
